import{quizData}from"./data.js";import{quizData2}from"./data2.js";let currentQuestionIndex=0;let traitScores={Openness:0,Conscientiousness:0,Extraversion:0,Agreeableness:0,Neuroticism:0};function displayTheQuestions(){const currentQuestion=quizData2.questions[currentQuestionIndex];const questionElement=document.getElementById("question-text");const answerElement=document.getElementById("answers");questionElement.textContent=currentQuestion.question;answerElement.innerHTML="";currentQuestion.answers.forEach(answer=>{const button=document.createElement("button");button.textContent=answer.text;button.className="answer-btn";button.addEventListener("click",()=>{handleAnswerClick(answer.trait)});answerElement.appendChild(button)});const questionNumberElement=currentQuestionIndex+1;document.getElementById("question-number").textContent=`Question ${questionNumberElement} of ${quizData2.questions.length}`}function showResult(){document.getElementById("quiz-container").style.display="none";document.getElementById("result-container").style.display="block";let allPokemon=[];for(let type in quizData2.results){quizData2.results[type].forEach(pokemon=>{allPokemon.push({...pokemon,type:type})})}const typeTraitMap={Fire:{Extraversion:2,Openness:2,Conscientiousness:0,Agreeableness:0,Neuroticism:-1},Water:{Extraversion:1,Openness:0,Conscientiousness:0,Agreeableness:1,Neuroticism:-1},Electric:{Extraversion:2,Openness:2,Conscientiousness:0,Agreeableness:0,Neuroticism:0},Grass:{Extraversion:0,Openness:0,Conscientiousness:1,Agreeableness:2,Neuroticism:0},Normal:{Extraversion:1,Openness:0,Conscientiousness:1,Agreeableness:1,Neuroticism:0},Psychic:{Extraversion:0,Openness:2,Conscientiousness:2,Agreeableness:0,Neuroticism:0},Dark:{Extraversion:0,Openness:1,Conscientiousness:0,Agreeableness:-1,Neuroticism:-1},Fighting:{Extraversion:1,Openness:0,Conscientiousness:1,Agreeableness:-1,Neuroticism:0},Bug:{Extraversion:0,Openness:1,Conscientiousness:2,Agreeableness:0,Neuroticism:0},Rock:{Extraversion:0,Openness:0,Conscientiousness:2,Agreeableness:0,Neuroticism:0}};allPokemon.forEach(pokemon=>{pokemon.score=0;const typeTraits=typeTraitMap[pokemon.type];for(let trait in traitScores){pokemon.score+=traitScores[trait]*typeTraits[trait]}});let resultPokemon=allPokemon[0];for(let i=1;i<allPokemon.length;i++){if(allPokemon[i].score>resultPokemon.score){resultPokemon=allPokemon[i]}}let highestTrait="";let highestScore=0;for(let trait in traitScores){if(traitScores[trait]>highestScore){highestScore=traitScores[trait];highestTrait=trait}}document.getElementById("pokemon-name").textContent=resultPokemon.name;document.getElementById("pokemon-image").src=resultPokemon.imageUrl;document.getElementById("pokemon-description").textContent=resultPokemon.description;document.getElementById("pokemon-nature").textContent=resultPokemon.nature;document.getElementById("pokedex-number").textContent=`#${resultPokemon.pokedexNumber}`;const traitScoresElement=document.getElementById("trait-scores");traitScoresElement.innerHTML="";for(let trait in traitScores){const traitDivElement=document.createElement("div");traitDivElement.className="trait-score";traitDivElement.innerHTML=`\n      <div class='trait-name'>${trait}</div>\n      <div class='trait-value'>${traitScores[trait]}</div>\n    `;traitScoresElement.appendChild(traitDivElement)}}function handleAnswerClick(trait){traitScores[trait]+=1;currentQuestionIndex+=1;if(currentQuestionIndex<quizData2.questions.length){displayTheQuestions()}else{showResult()}}displayTheQuestions();document.getElementById("restart-btn").addEventListener("click",()=>{currentQuestionIndex=0;traitScores={Openness:0,Conscientiousness:0,Extraversion:0,Agreeableness:0,Neuroticism:0};document.getElementById("result-container").style.display="none";document.getElementById("quiz-container").style.display="block";displayTheQuestions()});document.getElementById("start-btn").addEventListener("click",()=>{document.getElementById("landing-container").style.display="none";document.getElementById("quiz-container").style.display="block";displayTheQuestions()});